basic.sql:
CREATE LIBRARY lib AS BEGIN
  PUBLIC FUNCTION f(a INT) RETURNS b INT AS
  BEGIN
    b = :a + 1;
  END;
END;

or_replace_language.sql:
CREATE OR REPLACE LIBRARY s.lib LANGUAGE SQLSCRIPT AS BEGIN
  PUBLIC VARIABLE v INT CONSTANT = 1;
END;

all_options.sql:
CREATE OR REPLACE PROCEDURE s.p (IN a INT)
LANGUAGE SQLSCRIPT SQL SECURITY INVOKER DEFAULT SCHEMA s READS SQL DATA
DETERMINISTIC WITH ENCRYPTION AUTOCOMMIT DDL OFF AS
BEGIN SEQUENTIAL EXECUTION
  SELECT :a FROM DUMMY;
END;

any_table_parameter.sql:
CREATE PROCEDURE p (IN itab TABLE(...), OUT otab TABLE(...)) AS
BEGIN
  otab = SELECT * FROM :itab;
END;

array_parameter.sql:
CREATE PROCEDURE p (IN a INTEGER ARRAY) AS
BEGIN
  SELECT CARDINALITY(:a) FROM DUMMY;
END;

autocommit_ddl_off.sql:
CREATE PROCEDURE p AUTOCOMMIT DDL OFF AS
BEGIN
  SELECT * FROM t;
END;

autocommit_ddl_on.sql:
CREATE PROCEDURE p AUTOCOMMIT DDL ON AS
BEGIN
  SELECT * FROM t;
END;

basic.sql:
CREATE PROCEDURE p AS
BEGIN
  SELECT * FROM t;
END;

body_call.sql:
CREATE PROCEDURE p AS
BEGIN
  CALL q(1, ?);
END;

body_continue_handler.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE CONTINUE HANDLER FOR SQL_ERROR_CODE 301, SQLWARNING SELECT 1 FROM DUMMY;
  INSERT INTO t VALUES (1);
END;

body_declare_array.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE arr INTEGER ARRAY = ARRAY(1, 2, 3);
  arr[1] := 4;
END;

body_declare_auto.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE v AUTO = 1;
END;

body_declare_condition.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE my_err CONDITION;
  DECLARE dup_key CONDITION FOR SQL_ERROR_CODE 301;
END;

body_declare_cursor.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE CURSOR c (p_a INT) FOR SELECT a FROM t WHERE a > :p_a;
  DECLARE v INT;
  OPEN c(1);
  FETCH c INTO v;
  CLOSE c;
END;

body_declare_row_variable.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE r ROW (a INT, b NVARCHAR(10));
END;

body_declare_scalar.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE v1, v2 INTEGER = 0;
  DECLARE v3 CONSTANT NVARCHAR(10) DEFAULT 'x';
  DECLARE v4 NOT NULL DEFAULT 1;
  v1 := 5;
END;

body_declare_table_variable.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE tv TABLE (a INT, b NVARCHAR(10));
  DECLARE tv2 TABLE LIKE t;
END;

body_dml.sql:
CREATE PROCEDURE p (IN a INT) AS
BEGIN
  INSERT INTO t VALUES (:a);
  UPDATE t SET c = 1 WHERE a = :a;
  DELETE FROM t WHERE a = :a;
END;

body_exec_dynamic_sql.sql:
CREATE PROCEDURE p (IN n NVARCHAR(20)) AS
BEGIN
  EXEC 'SELECT * FROM ' || :n;
END;

body_execute_immediate.sql:
CREATE PROCEDURE p (IN a NVARCHAR(12)) AS
BEGIN
  EXECUTE IMMEDIATE 'SELECT * FROM ' || :a READS SQL DATA;
END;

body_exit_handler.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION SELECT ::SQL_ERROR_CODE FROM DUMMY;
  SELECT * FROM t;
END;

body_for_cursor.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE CURSOR c FOR SELECT a FROM t;
  FOR r AS c DO
    INSERT INTO t2 VALUES (:r.a);
  END FOR;
END;

body_for_range.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE s INT = 0;
  FOR i IN 1..10 DO
    s = :s + :i;
  END FOR;
END;

body_for_reverse.sql:
CREATE PROCEDURE p AS
BEGIN
  FOR i IN REVERSE 1..10 DO
    INSERT INTO t VALUES (:i);
  END FOR;
END;

body_foreach.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE arr INTEGER ARRAY = ARRAY(1, 2, 3);
  FOREACH x IN :arr DO
    INSERT INTO t VALUES (:x);
  END FOR;
END;

body_if.sql:
CREATE PROCEDURE p (IN a INT) AS
BEGIN
  IF :a > 1 THEN
    SELECT 1 FROM DUMMY;
  ELSEIF :a = 1 THEN
    SELECT 2 FROM DUMMY;
  ELSE
    SELECT 3 FROM DUMMY;
  END IF;
END;

body_loop_break_continue.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE i INT = 0;
  LOOP
    i = :i + 1;
    IF :i > 10 THEN
      BREAK;
    END IF;
    CONTINUE;
  END LOOP;
END;

body_nested_block.sql:
CREATE PROCEDURE p AS
BEGIN
  BEGIN SEQUENTIAL EXECUTION AUTONOMOUS TRANSACTION
    INSERT INTO t VALUES (1);
  END;
END;

body_resignal.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION RESIGNAL;
  SELECT * FROM t;
END;

body_return.sql:
CREATE PROCEDURE p AS
BEGIN
  RETURN;
END;

body_signal.sql:
CREATE PROCEDURE p AS
BEGIN
  SIGNAL SQL_ERROR_CODE 10001 SET MESSAGE_TEXT = 'custom error';
END;

body_table_variable_assign.sql:
CREATE PROCEDURE p (OUT o t) AS
BEGIN
  tv = SELECT * FROM t;
  o = SELECT * FROM :tv WHERE a > 1;
END;

body_tabvar_search.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE pos INT;
  pos = :tv.SEARCH((key1, key2), ('I', 3));
END;

body_using_library.sql:
CREATE PROCEDURE p AS
BEGIN
  USING s.lib AS l;
  SELECT * FROM t;
END;

body_while.sql:
CREATE PROCEDURE p AS
BEGIN
  DECLARE i INT = 0;
  WHILE :i < 10 DO
    i = :i + 1;
  END WHILE;
END;

default_schema.sql:
CREATE PROCEDURE p DEFAULT SCHEMA s AS
BEGIN
  SELECT * FROM t;
END;

deterministic.sql:
CREATE PROCEDURE p (IN a INT, OUT b INT) DETERMINISTIC AS
BEGIN
  b = :a + 1;
END;

inline_table_type_parameter.sql:
CREATE PROCEDURE p (IN itab TABLE (a INT, b NVARCHAR(10)), OUT otab TABLE (a INT)) AS
BEGIN
  otab = SELECT a FROM :itab;
END;

language_sqlscript.sql:
CREATE PROCEDURE p LANGUAGE SQLSCRIPT AS
BEGIN
  SELECT * FROM t;
END;

or_replace.sql:
CREATE OR REPLACE PROCEDURE p AS
BEGIN
  SELECT * FROM t;
END;

parameter_default.sql:
CREATE PROCEDURE p (IN a INTEGER DEFAULT 5) AS
BEGIN
  SELECT :a FROM DUMMY;
END;

reads_sql_data.sql:
CREATE PROCEDURE p READS SQL DATA AS
BEGIN
  SELECT * FROM t;
END;

reads_sql_data_result_view.sql:
CREATE PROCEDURE p (IN id INT, OUT o1 t) LANGUAGE SQLSCRIPT READS SQL DATA WITH RESULT VIEW v AS
BEGIN
  o1 = SELECT * FROM t WHERE c = :id;
END;

scalar_parameters.sql:
CREATE PROCEDURE p (IN a INTEGER, OUT b NVARCHAR(10), INOUT c DECIMAL(10, 2)) AS
BEGIN
  b = 'x';
END;

schema_qualified.sql:
CREATE PROCEDURE s.p() AS
BEGIN
  SELECT * FROM t;
END;

sequential_execution.sql:
CREATE PROCEDURE p AS
BEGIN SEQUENTIAL EXECUTION
  SELECT * FROM t;
END;

sql_security_definer.sql:
CREATE PROCEDURE p LANGUAGE SQLSCRIPT SQL SECURITY DEFINER AS
BEGIN
  SELECT * FROM t;
END;

sql_security_invoker.sql:
CREATE PROCEDURE p LANGUAGE SQLSCRIPT SQL SECURITY INVOKER AS
BEGIN
  SELECT * FROM t;
END;

table_type_parameter.sql:
CREATE PROCEDURE p (IN itab s.tt, OUT otab s.tt) AS
BEGIN
  otab = SELECT * FROM :itab;
END;

variable_cache.sql:
CREATE PROCEDURE p VARIABLE CACHE ON x ENABLE AS
BEGIN
  x = SELECT * FROM t;
  SELECT * FROM :x;
END;

variable_cache_list.sql:
CREATE PROCEDURE p VARIABLE CACHE ON (x, y) ENABLE, z DISABLE AS
BEGIN
  x = SELECT * FROM t;
  y = SELECT * FROM t;
  z = SELECT * FROM t;
END;

variable_cache_without_mode.sql:
CREATE PROCEDURE p VARIABLE CACHE ON x, y AS
BEGIN
  x = SELECT * FROM t;
  y = SELECT * FROM t;
END;

with_encryption.sql:
CREATE PROCEDURE p WITH ENCRYPTION AS
BEGIN
  SELECT * FROM t;
END;

declare_and_body.sql:
CREATE TRIGGER trg AFTER INSERT ON t FOR EACH ROW
BEGIN
  DECLARE cnt INT;
  SELECT COUNT(*) INTO cnt FROM log;
  IF :cnt = 0 THEN
    INSERT INTO log VALUES (5);
  END IF;
END;

where_current_of.sql:
DO BEGIN
  DECLARE CURSOR cur FOR SELECT a FROM t FOR UPDATE;
  FOR r AS cur DO
    DELETE FROM t WHERE CURRENT OF cur;
  END FOR;
END;
